#!/usr/bin/env python3
import hashlib,json,re,subprocess,sys
from pathlib import Path
d=Path(__file__).resolve().parents[2];p=d/'research/nine-seed38-jones-prefix-path18-20-check';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest()
for n,h in {'run.py':'f559a41fda1266565ad53d0014220720586591f1777ec583fa96d44fced375d2','provider_preflight.py':'a99949fb4117a516c835605ddee485083278f18265f0fed32558cf4e9f8fd718','source-manifest.json':'ff098580cc42cd9649b8fc4654788d2af1c925a1753add0a2afa2e2db47a9b5c','src/DiophantineConsistency/Norm38MacroPath18to20.lean':'0d5129bfa5fc3fedc920db2a484fc6ab83f4f364350f936490640d4e95ea7196'}.items():assert sha(p/n)==h
s=(p/'src/DiophantineConsistency/Norm38MacroPath18to20.lean').read_text();rows=json.loads((p/'source-manifest.json').read_text())['rows'];assert len(rows)==1 and rows[0]['source_sha256']=='0d5129bfa5fc3fedc920db2a484fc6ab83f4f364350f936490640d4e95ea7196';assert re.findall(r'^import ([\w.]+)$',s,re.M)==rows[0]['imports']==['DiophantineConsistency.Norm38MacroDependentOutput','DiophantineConsistency.Norm38MacroPrefixEmbedding'];assert re.findall(r'^theorem (\w+)',s,re.M)==['path18_20','lookup18_20'];assert re.findall(r'^#print axioms (\w+)',s,re.M)==['path18_20','lookup18_20']
for q in ['PrefixPath d18 d20 (fun i => i.castSucc.castSucc)','PrefixPath.step (PrefixPath.step (PrefixPath.base d18) _) _','d20.values a i.castSucc.castSucc = d18.values a i']:assert q in s
nodes=(d/'research/nine-seed38-jones-named-prefix-check/src/DiophantineConsistency/Norm38MacroPrefixes.lean').read_text();assert 'def d19 : Dag 19 := .snoc d18 ' in nodes and 'def d20 : Dag 20 := .snoc d19 ' in nodes
r=subprocess.run([sys.executable,'-I','-S','-B',str(p/'run.py'),'--preflight'],capture_output=True,text=True,check=True,timeout=300);o=json.loads(r.stdout);assert not r.stderr and o['status']=='PASS_NO_LEAN_PREFLIGHT' and o['stage_count']==1
print(json.dumps({'status':'PASS','preflight':o,'scope':'concrete two-snoc path source and point-provider review; no Lean replay'},indent=2,sort_keys=True))
